def sol(n, lost, reserve):
    missing = set(lost) - set(reserve)
    surplus = set(reserve) - set(lost)
    for student in sorted(missing):
        if student - 1 in surplus:
            surplus.remove(student - 1)
        elif student + 1 in surplus:
            surplus.remove(student + 1)
        else:
            n -= 1
    return n

